SELECT

id,

create_time, update_time,

organ_id, knowledge_id, revision_no, source_type, revision_status, source_file_name, source_content_type, source_storage_path, source_sha256, source_file_size, parser_name, parser_version, parser_task_id, parsed_storage_path, chunk_count, index_status, embedding_profile, embedding_model, index_completed_time, priority, reviewer_user_id, review_time, review_comment, create_user_id, faq_question, faq_answer, tags_json,

delete_flag,

version
FROM knowledge_revision



        AND id = #{id, jdbcType=BIGINT}


        AND id IN

            #{item, jdbcType=BIGINT}





            AND create_time >= #{createTime[0], jdbcType=TIMESTAMP}


            AND create_time <= #{createTime[1], jdbcType=TIMESTAMP}


            AND create_time BETWEEN #{createTime[0], jdbcType=TIMESTAMP}
            AND #{createTime[1], jdbcType=TIMESTAMP}




            AND update_time >= #{updateTime[0], jdbcType=TIMESTAMP}


            AND update_time <= #{updateTime[1], jdbcType=TIMESTAMP}


            AND update_time BETWEEN #{updateTime[0], jdbcType=TIMESTAMP}
            AND #{updateTime[1], jdbcType=TIMESTAMP}




        AND organ_id = #{organId, jdbcType=BIGINT}


        AND knowledge_id = #{knowledgeId, jdbcType=BIGINT}


        AND revision_no = #{revisionNo, jdbcType=VARCHAR}


        AND source_type = #{sourceType, jdbcType=VARCHAR}


        AND revision_status = #{revisionStatus, jdbcType=VARCHAR}


        AND source_file_name = #{sourceFileName, jdbcType=VARCHAR}


        AND source_content_type = #{sourceContentType, jdbcType=VARCHAR}


        AND source_storage_path = #{sourceStoragePath, jdbcType=VARCHAR}


        AND source_sha256 = #{sourceSha256, jdbcType=CHAR}


        AND source_file_size = #{sourceFileSize, jdbcType=BIGINT}


        AND parser_name = #{parserName, jdbcType=VARCHAR}


        AND parser_version = #{parserVersion, jdbcType=VARCHAR}


        AND parser_task_id = #{parserTaskId, jdbcType=VARCHAR}


        AND parsed_storage_path = #{parsedStoragePath, jdbcType=VARCHAR}


        AND chunk_count = #{chunkCount, jdbcType=INTEGER}


        AND index_status = #{indexStatus, jdbcType=VARCHAR}


        AND embedding_profile = #{embeddingProfile, jdbcType=VARCHAR}


        AND embedding_model = #{embeddingModel, jdbcType=VARCHAR}


        AND index_completed_time = #{indexCompletedTime, jdbcType=TIMESTAMP}


        AND priority = #{priority, jdbcType=INTEGER}


        AND reviewer_user_id = #{reviewerUserId, jdbcType=BIGINT}


        AND review_time = #{reviewTime, jdbcType=TIMESTAMP}


        AND review_comment = #{reviewComment, jdbcType=VARCHAR}


        AND create_user_id = #{createUserId, jdbcType=BIGINT}


        AND faq_question = #{faqQuestion, jdbcType=LONGVARCHAR}


        AND faq_answer = #{faqAnswer, jdbcType=LONGVARCHAR}


        AND tags_json = #{tagsJson, jdbcType=LONGVARCHAR}


    AND (delete_flag = 0 OR delete_flag IS NULL)
